    smu, ssd = float(sv.mean()), float(sv.std())
    return_scale = float(panel.tail(200).pct_change().std(axis=1, ddof=0).median()) if len(panel) >= 40 else 0.01
    if not isfinite(return_scale) or return_scale <= 0:
        return_scale = 0.01
