    for a in assets:
        wts[a] = 0.70 * wts[a] + 0.30 * regime_w.get(a, 1.0 / len(assets))
    # clamp
    for _ in range(60):
        excess = sum(max(0.0, x - MAX_W) for x in wts.values())
        wts = {a: min(MAX_W, max(MIN_W, x)) for a, x in wts.items()}
        room = [a for a in wts if wts[a] < MAX_W - 1e-12]
