        for a in room:
            wts[a] += excess * (regime_w.get(a, 0.0) / den if den else 1.0 / len(room))
    s = sum(wts.values())
    wts = {a: x / s for a, x in wts.items()}
    wts[assets[-1]] += 1.0 - sum(wts.values())
    return wts


