    avg_px = float(panel.mean(axis=1).iloc[-1]) if len(panel) else 0.0
    ma60 = float(panel.mean(axis=1).tail(60).mean()) if len(panel) >= 60 else avg_px
    bearish = trend20 < 0.0 and avg_px < ma60
