        for fid, _, _ in ensemble:
            try:
                if fid == "trend_r2_30_signed":
                    v = _trend_r2(c)
                elif fid == "semi_down_ratio_20":
                    v = _semi_down_ratio(r)
                elif fid == "mom_120d_skip5":
                    v = _mom_120(c)
                elif fid == "mom_10d_skip5":
                    v = _mom_10(c)
                elif fid == "vol_of_vol20x60":
                    v = _vol_of_vol(r)
                elif fid == "time_under_water_120":
