  vol_of_vol20x60       w=0.0739 dir=+1  60d std of 20d realized vol
  time_under_water_120  w=0.0661 dir=-1  days since last 120d rolling high
  vix_beta_cond_60x20   w=0.0576 dir=-1  -beta(asset,VIX,60) * 20d VIX move
