    s = r.dropna().tail(120)
    if len(s) < 90:
        return None
    v = s.rolling(20).std()
    out = v.rolling(60).std().iloc[-1]
    return None if not isfinite(out) else float(out)


def _kurt_20(r):
    s = r.dropna().tail(40)
    if len(s) < 20:
        return None
